    if(MutationInvalidationGate())return 1;
    constexpr double quantum=0x1p-32;std::int64_t canonical{},adjacent{},different{};if(!RootMotionInternal::NormalizedClockToQ32(.25,canonical)||!RootMotionInternal::NormalizedClockToQ32(std::nextafter(.25,.5),adjacent)||!RootMotionInternal::NormalizedClockToQ32(.25+quantum,different)||canonical!=adjacent||canonical==different||!RootMotionInternal::NormalizedClockToQ32(-0.0,canonical)||canonical!=0||!RootMotionInternal::NormalizedClockToQ32(-2147483648.0,canonical)||canonical!=(std::numeric_limits<std::int64_t>::min)()||RootMotionInternal::NormalizedClockToQ32(2147483648.0,canonical)||RootMotionInternal::NormalizedClockToQ32((std::numeric_limits<double>::infinity)(),canonical))return Fail("Q32.32 clock contract failed");std::int64_t accumulated{};for(std::size_t i=0;i<100000;++i){std::int64_t next{};if(!RootMotionInternal::AdvanceNormalizedClockQ32(accumulated,.0001,next))return Fail("Q32.32 long-run failed");accumulated=next;}if(std::abs(std::ldexp(double(accumulated),-32)-10.0)>1.2e-5||!std::isfinite(RootMotionInternal::WrappedPhaseQ32(accumulated))||std::abs(RootMotionInternal::WrappedPhaseQ32(-1)-(1.0-quantum))>quantum*.5)return Fail("Q32.32 long-run/seam error failed");std::int64_t overflowSentinel=77;if(RootMotionInternal::AdvanceNormalizedClockQ32((std::numeric_limits<std::int64_t>::max)(),quantum,overflowSentinel)||overflowSentinel!=77)return Fail("Q32.32 overflow was not atomic");
    for(const double yaw:{1e-12,3.14159265358979323846-1e-9,3.14159265358979323846+1e-9}){RootMotionInternal::Motion3D motion{1.25,.5,-.75,yaw},roundTrip{};RootMotionInternal::Twist3D twist{};if(!RootMotionInternal::LogSE2(motion,twist)||!RootMotionInternal::ExpSE2(twist,roundTrip)||std::abs(roundTrip.x-motion.x)>1e-9||std::abs(roundTrip.y-motion.y)>1e-9||std::abs(roundTrip.z-motion.z)>1e-9||std::abs(RootMotionInternal::NormalizeYaw(roundTrip.yaw-motion.yaw))>1e-9)return Fail("SE2 Log/Exp oracle failed");const auto identity=RootMotionInternal::Compose(motion,RootMotionInternal::Inverse(motion));if(std::abs(identity.x)>1e-9||std::abs(identity.y)>1e-9||std::abs(identity.z)>1e-9||std::abs(identity.yaw)>1e-9)return Fail("SE2 inverse oracle failed");}
    const auto skeleton=Rig();const auto map=Map();const auto straight=Clip({1,0,0},0),turn=Clip({0,0,1},1.57079632679f);RootMotionInternal::Motion3D largeMotion{},reverseMotion{};std::int64_t crossed{};const std::int64_t largeBase=(std::int64_t{2147483647}<<32)+123456789,largeNext=largeBase+(std::int64_t{1}<<30);if(!RootMotionInternal::ExtractIntervalQ32(skeleton,straight,0,largeBase,largeNext,8,false,largeMotion,crossed)||crossed!=0||!Near(float(largeMotion.x),.25f,.00001f)||!RootMotionInternal::ExtractIntervalQ32(skeleton,straight,0,largeNext,largeBase,8,false,reverseMotion,crossed)||crossed!=0||!Near(float(reverseMotion.x),-.25f,.00001f))return Fail("large-cycle Q32.32 interval failed");const std::array<AnimationBlendSample1D3D,1> straightSamples{{{0,&straight}}},turnSamples{{{0,&turn}}};const std::array<AnimationGraphState3D,2> states{{{"Straight",straightSamples},{"Turn",turnSamples}}};AnimationGraph3D phaseA,phaseB;AnimationGraphError3D error{};auto phasePoseA=Pose(skeleton,straight,.25f),phasePoseB=Pose(skeleton,straight,.2501f);AnimationGraphRootMotionResult3D phaseResultA{},phaseResultB{};if(!phaseA.Initialize(skeleton,map.compatibility,states,&error)||!phaseB.Initialize(skeleton,map.compatibility,states,&error)||!phaseA.SetNormalizedPhase(.25f)||!phaseB.SetNormalizedPhase(.2501f)||!phaseA.PrepareRootMotion(map,map.compatibility,{})||!phaseB.PrepareRootMotion(map,map.compatibility,{})||!phaseA.EvaluateRootMotionTick(skeleton,map.compatibility,{1,.001,1},phasePoseA,&phaseResultA)||!phaseB.EvaluateRootMotionTick(skeleton,map.compatibility,{1,.001,1},phasePoseB,&phaseResultB)||phaseResultA.deterministicHash==phaseResultB.deterministicHash)return Fail("distinct phase state hash collision");AnimationGraph3D graph;if(!graph.Initialize(skeleton,map.compatibility,states,&error)||!graph.PrepareRootMotion(map,map.compatibility,{}))return Fail("prepare failed");auto pose=Pose(skeleton,straight,0);AnimationGraphRootMotionPreviewToken3D token{};AnimationGraphRootMotionResult3D preview{},result{};const auto poseBefore=pose;if(!graph.PreviewRootMotionTick(skeleton,map.compatibility,{1,.1,1},pose,token,&preview)||!Same(pose,poseBefore)||!graph.CanCommitRootMotionPreview(token,pose)||!graph.CommitRootMotionPreview(token,pose,&result)||result.delta.translationModel.x!=0)return Fail("anchor transaction failed");
    if(!graph.EvaluateRootMotionTick(skeleton,map.compatibility,{2,.1,1},pose,&result)||!Near(result.delta.translationModel.x,.1f)||result.activeLeaves!=1)return Fail("single leaf interval failed");if(!graph.SetState(1,1,true)||!graph.PreviewRootMotionTick(skeleton,map.compatibility,{3,.1,1},pose,token,&preview)||preview.activeLeaves!=2||preview.transitionWeight<=0||preview.transitionWeight>=1)return Fail("crossfade preview failed");RootMotionInternal::Motion3D straightMotion{},turnMotion{},oracle{};RootMotionInternal::Twist3D straightTwist{},turnTwist{},blended{};std::int64_t ignored{};if(!RootMotionInternal::ExtractInterval(skeleton,straight,0,.2,.3,8,false,straightMotion,ignored)||!RootMotionInternal::ExtractInterval(skeleton,turn,0,.2,.3,8,false,turnMotion,ignored)||!RootMotionInternal::LogSE2(straightMotion,straightTwist)||!RootMotionInternal::LogSE2(turnMotion,turnTwist))return Fail("crossfade oracle extraction failed");blended={straightTwist.x*.95+turnTwist.x*.05,0,straightTwist.z*.95+turnTwist.z*.05,straightTwist.yaw*.95+turnTwist.yaw*.05};if(!RootMotionInternal::ExpSE2(blended,oracle)||!Near(preview.delta.translationModel.x,float(oracle.x))||!Near(preview.delta.translationModel.z,float(oracle.z))||!Near(preview.delta.yawRadians,float(oracle.yaw)))return Fail("crossfade average twist mismatch");auto stale=token;if(!graph.CommitRootMotionPreview(token,pose,&result))return Fail("crossfade commit failed");
    AnimationGraphRootMotionResult3D sentinel{};std::memset(&sentinel,0x5a,sizeof(sentinel));const auto sentinelBefore=sentinel;if(graph.CommitRootMotionPreview(stale,pose,&sentinel)||std::memcmp(&sentinel,&sentinelBefore,sizeof(sentinel)))return Fail("stale token/output atomicity failed");if(!graph.PreviewRootMotionTick(skeleton,map.compatibility,{4,.1,1},pose,token,&preview))return Fail("update invalidation setup failed");const auto updatePose=pose;graph.Update((std::numeric_limits<float>::quiet_NaN)());graph.Update(0);if(!graph.CanCommitRootMotionPreview(token,pose))return Fail("invalid/no-op update invalidated preview");graph.Update(.01f);if(graph.CanCommitRootMotionPreview(token,pose)||graph.CommitRootMotionPreview(token,pose,&sentinel)||!Same(pose,updatePose)||std::memcmp(&sentinel,&sentinelBefore,sizeof(sentinel)))return Fail("phase update committed stale preview");if(!graph.PreviewRootMotionTick(skeleton,map.compatibility,{4,.1,1},pose,token,&preview))return Fail("pose mutation setup failed");auto originalPose=pose;pose.localTransforms[1].translation.x=.25f;if(graph.CommitRootMotionPreview(token,pose,&sentinel)||std::memcmp(&sentinel,&sentinelBefore,sizeof(sentinel)))return Fail("pose mutation committed");pose=originalPose;if(graph.TeleportRootMotion((std::numeric_limits<std::uint64_t>::max)()))return Fail("maximum teleport accepted");if(!graph.TeleportRootMotion(40)||!graph.EvaluateRootMotionTick(skeleton,map.compatibility,{41,.1,1},pose,&result)||result.delta.translationModel.x!=0||result.delta.translationModel.y!=0||result.delta.translationModel.z!=0||result.delta.yawRadians!=0)return Fail("teleport anchor failed");
    for(unsigned i=0;i<6;++i)if(!graph.SetState(i&1,.5f,true))return Fail("bounded interruption failed");constexpr std::size_t Iterations=10000;std::vector<long long> samples;samples.reserve(Iterations);const auto beforeAllocation=allocations.load();std::uint64_t hash{};for(std::size_t i=0;i<Iterations;++i){const auto begin=std::chrono::steady_clock::now();if(!graph.EvaluateRootMotionTick(skeleton,map.compatibility,{42+i,.0001,1},pose,&result))return Fail("benchmark tick failed");samples.push_back(std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-begin).count());hash^=result.deterministicHash;}const auto afterAllocation=allocations.load();std::sort(samples.begin(),samples.end());const auto p95=samples[(samples.size()*95+99)/100-1];if(afterAllocation!=beforeAllocation||p95>250000)return Fail("performance/allocation gate failed");constexpr std::uint64_t ExpectedReplayHash=15292123305586799199ull;if(hash!=ExpectedReplayHash)return Fail("cross-process deterministic hash gate failed");std::printf("AnimationGraphRootMotion3D PASS p95=%lldns alloc=%llu hash=%llu leaves=%u",p95,(unsigned long long)(afterAllocation-beforeAllocation),(unsigned long long)hash,result.activeLeaves);if(LeafCapacityBenchmark(skeleton,map))return 1;const auto retained=graph.MemoryStats().retainedCapacityBytes;graph.Reset();const auto reclaimable=graph.MemoryStats().reclaimableCapacityBytes,released=graph.TrimUnusedMemory();const auto memory=graph.MemoryStats();if(!retained||reclaimable!=retained||released!=retained||memory.lastReleasedBytes!=released||!memory.trimCount)return Fail("memory lifecycle failed");std::printf("\n");return 0;
